package com.voznipark.maintenance.entity;

import jakarta.persistence.*;
import lombok.*;

import java.time.Instant;

/**
 * Tracks cumulative mileage per vehicle from completed travel orders.
 * vehicleId is the PK — a cross-service reference from fleet-service, not generated by the DB.
 */
@Entity
@Table(name = "vehicle_mileage_tracker")
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class VehicleMileageTracker {

    @Id
    @Column(name = "vehicle_id")
    private Long vehicleId;

    @Column(name = "vehicle_sap_number")
    private Integer vehicleSapNumber;

    @Column(name = "total_mileage_km", nullable = false)
    private Integer totalMileageKm;

    @Column(name = "km_since_last_minor_service", nullable = false)
    private Integer kmSinceLastMinorService;

    @Column(name = "km_since_last_major_service", nullable = false)
    private Integer kmSinceLastMajorService;

    @Column(name = "last_travel_order_id")
    private Long lastTravelOrderId;

    @Column(name = "last_updated")
    private Instant lastUpdated;
}
